export interface ErrorStackOptions {
  mode?: 'off' | 'string' | 'frames';
  normalizeNewlines?: boolean;
  trimLeadingWhitespace?: boolean;
  maxStackLines?: number;
  stripInternalFrames?: 'none' | 'node' | 'superjson' | 'node_and_superjson';
  redactPaths?: 'none' | 'basename' | 'strip_cwd';
  includeCauses?: 'none' | 'direct' | 'deep';
  maxCauseDepth?: number;
  sanitizeMessage?: boolean;
  classFilter?: string[];
}

export interface NormalizedErrorStackOptions {
  mode: 'off' | 'string' | 'frames';
  normalizeNewlines: boolean;
  trimLeadingWhitespace: boolean;
  maxStackLines?: number;
  stripInternalFrames: 'none' | 'node' | 'superjson' | 'node_and_superjson';
  redactPaths: 'none' | 'basename' | 'strip_cwd';
  includeCauses: 'none' | 'direct' | 'deep';
  maxCauseDepth: number;
  sanitizeMessage: boolean;
  classFilter: string[];
}

export function normalizeErrorStackOptions(input: unknown): NormalizedErrorStackOptions | undefined {
  if (input === null || typeof input !== 'object' || Array.isArray(input)) return undefined;
  const o = input as ErrorStackOptions;
  let mode = o.mode === 'string' || o.mode === 'frames' ? o.mode : 'off';
  if (o.maxStackLines !== undefined && (!Number.isInteger(o.maxStackLines) || o.maxStackLines <= 0)) mode = 'off';
  const includeCauses = o.maxCauseDepth !== undefined && !Number.isInteger(o.maxCauseDepth)
    ? 'none' : o.includeCauses === 'direct' || o.includeCauses === 'deep' ? o.includeCauses : 'none';
  return {
    mode,
    normalizeNewlines: o.normalizeNewlines === true,
    trimLeadingWhitespace: o.trimLeadingWhitespace !== false,
    maxStackLines: o.maxStackLines,
    stripInternalFrames: o.stripInternalFrames === 'node' || o.stripInternalFrames === 'superjson' || o.stripInternalFrames === 'node_and_superjson' ? o.stripInternalFrames : 'none',
    redactPaths: o.redactPaths === 'basename' || o.redactPaths === 'strip_cwd' ? o.redactPaths : 'none',
    includeCauses,
    maxCauseDepth: o.maxCauseDepth ?? 16,
    sanitizeMessage: o.sanitizeMessage === true,
    classFilter: Array.isArray(o.classFilter) ? [...o.classFilter] : [],
  };
}

export function sanitizeMessage(message: string): string {
  return message.replace(/https?:\/\/[^\s]+|[\w.+-]+@[\w.-]+\.[a-zA-Z]{2,}|\b(?:\d{1,3}\.){3}\d{1,3}\b/gi, '[redacted]');
}

export type Processor = (error: any) => any;

export class ErrorClassRegistry {
  private readonly processors = new Map<string, Processor>();

  register(name: string, fn: Processor): void {
    this.processors.set(name, fn);
  }

  has(name: string): boolean {
    return this.processors.has(name);
  }

  getProcessor(name: string): Processor | undefined {
    return this.processors.get(name);
  }
}

import { NormalizedErrorStackOptions } from './error-options.js';

export function normalizeStackNewlines(stack: string): string {
  return stack.replace(/\r\n?/g, '\n');
}

function lines(stack: string, options: NormalizedErrorStackOptions): string[] {
  const value = options.normalizeNewlines ? normalizeStackNewlines(stack) : stack;
  const result = value.split('\n');
  return options.trimLeadingWhitespace ? result.map((line, i) => i ? line.replace(/^[\t ]+/, '') : line) : result;
}

function strip(lines: string[], options: NormalizedErrorStackOptions): string[] {
  return lines.filter((line, i) => {
    if (!i) return true;
    const mode = options.stripInternalFrames;
    if ((mode === 'node' || mode === 'node_and_superjson') && line.includes('node:internal')) return false;
    if ((mode === 'superjson' || mode === 'node_and_superjson') && /src[\\/](?:transformer|plainer|index)\.ts/.test(line)) return false;
    return true;
  });
}

function redact(lines: string[], options: NormalizedErrorStackOptions): string[] {
  if (options.redactPaths === 'none') return lines;
  const cwd = typeof process !== 'undefined' && typeof process.cwd === 'function' ? process.cwd().replace(/\\/g, '/') : '';
  return lines.map((line, i) => {
    if (!i) return line;
    if (options.redactPaths === 'strip_cwd') {
      if (!cwd) return line;
      return line.replace(/\\/g, '/').split(cwd + '/').join('');
    }
    return line.replace(/(?:file:\/\/)?(?:[A-Za-z]:)?(?:[\\/][^\s():\\/]+)+/g, path => path.split(/[\\/]/).pop() || path);
  });
}

export function processStackString(stack: string, options: NormalizedErrorStackOptions): string {
  let result = redact(lines(stack, options), options);
  if (options.maxStackLines !== undefined) result = result.slice(0, options.maxStackLines);
  return strip(result, options).join('\n');
}

export function processStackFrames(stack: string, options: NormalizedErrorStackOptions): { raw: string }[] {
  let result = redact(strip(lines(stack, options), options), options);
  if (options.maxStackLines !== undefined) result = result.slice(0, options.maxStackLines);
  return result.map(raw => ({ raw }));
}

