import SuperJSON from './index.js';
import { processStackString, processStackFrames } from './error-stack.js';
import { sanitizeMessage } from './error-sanitizer.js';

function matchesError(v: Error, superJson: SuperJSON): boolean {
  const filter = superJson.errorStack?.classFilter;
  return !filter?.length || filter.includes(v.name);
}

function serializeError(v: Error, superJson: SuperJSON, seen = new Set<Error>(), depth = 0): any {
  const options = superJson.errorStack;
  const matching = matchesError(v, superJson);
  const result: any = {
    name: v.name,
    message: options?.sanitizeMessage && matching ? sanitizeMessage(v.message) : v.message,
  };
  seen.add(v);
  if (!options) {
    if ('cause' in v) result.cause = v.cause;
  } else if (options.includeCauses !== 'none' && depth < (options.includeCauses === 'direct' ? 1 : options.maxCauseDepth) && v.cause instanceof Error && !seen.has(v.cause)) {
    result.cause = serializeError(v.cause, superJson, seen, depth + 1);
  }
  superJson.allowedErrorProps.forEach(prop => {
    if (options && (prop === 'stack' || prop === 'stackFrames' || prop === 'cause')) return;
    result[prop] = (v as any)[prop];
  });
  if (options && matching && typeof v.stack === 'string') {
    if (options.mode === 'string' && superJson.allowedErrorProps.includes('stack')) result.stack = processStackString(v.stack, options);
    if (options.mode === 'frames' && superJson.allowedErrorProps.includes('stackFrames')) result.stackFrames = processStackFrames(v.stack, options);
  }
  if (typeof AggregateError !== 'undefined' && v instanceof AggregateError) result.errors = v.errors;
  const processor = superJson.errorClassRegistry.getProcessor(v.name);
  return processor ? processor(result) : result;
}

function deserializeError(v: any, superJson: SuperJSON): Error {
  const cause = v.cause && !(v.cause instanceof Error) && typeof v.cause === 'object' && typeof v.cause.name === 'string' ? deserializeError(v.cause, superJson) : v.cause;
  const e = v.name === 'AggregateError' && typeof AggregateError !== 'undefined' ? new AggregateError(v.errors || [], v.message, { cause }) : new Error(v.message, { cause });
  e.name = v.name;
  e.stack = v.stack;
  if (v.stackFrames !== undefined) {
    (e as any).stackFrames = v.stackFrames;
    e.stack = v.stackFrames.map((frame: { raw: string }) => frame.raw).join('\n');
  }
  superJson.allowedErrorProps.forEach(prop => {
    if (prop !== 'cause') (e as any)[prop] = v[prop];
  });
  return e;
}

